command:
cp -n /etc/nginx/sites-available/default /etc/nginx/sites-available/default.package
cat > /etc/nginx/sites-available/default <<'ANTRIEB_NGINX_EOF'
server {
    listen 5660 default_server;
    listen [::]:5660 default_server;
    server_name _;
    access_log /var/log/nginx/backend_access.log;

    location = / {
        default_type text/plain;
        add_header X-Backend-Node node3 always;
        return 200 "node3\n";
    }

    location / {
        return 404;
    }
}
ANTRIEB_NGINX_EOF

